Fetch all tickers on kucoin and print th.go:
Call `fetchTickers`, sort the tickers by `quoteVolume` (24h volume in the quote currency) descending and print the top 10.

```go
package main

import (
	"fmt"
	"sort"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func main() {
	exchange := ccxt.NewKucoin(nil)
	tickers, err := exchange.FetchTickers()
	if err != nil {
		fmt.Println(err)
		return
	}
	vol := func(t ccxt.Ticker) float64 {
		if t.QuoteVolume == nil {
			return 0
		}
		return *t.QuoteVolume
	}
	list := make([]ccxt.Ticker, 0, len(tickers.Tickers))
	for _, t := range tickers.Tickers {
		list = append(list, t)
	}
	sort.Slice(list, func(i, j int) bool { return vol(list[i]) > vol(list[j]) })
	for i, t := range list {
		if i >= 10 {
			break
		}
		symbol := ""
		if t.Symbol != nil {
			symbol = *t.Symbol
		}
		fmt.Println(symbol, vol(t))
	}
}
```

