Print the bid ask spread for XRP/USDT on.go:
Fetch the ticker with `fetchTicker` and subtract `bid` from `ask` to get the spread.

```go
package main

import (
	"fmt"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func deref(p *float64) float64 {
	if p == nil {
		return 0
	}
	return *p
}

func main() {
	exchange := ccxt.NewMexc(nil)
	ticker, err := exchange.FetchTicker("XRP/USDT")
	if err != nil {
		fmt.Println(err)
		return
	}
	bid := deref(ticker.Bid)
	ask := deref(ticker.Ask)
	spread := ask - bid
	pct := 0.0
	if bid > 0 {
		pct = spread / bid * 100
	}
	fmt.Printf("bid=%v ask=%v spread=%v (%.4f%%)\n", bid, ask, spread, pct)
}
```

