Print the 24h percentage change for the.go:
Fetch all tickers with `fetchTickers`, sort by the `percentage` field and print the 10 biggest gainers and losers.

```go
package main

import (
	"fmt"
	"sort"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func main() {
	exchange := ccxt.NewBinance(nil)
	tickers, err := exchange.FetchTickers()
	if err != nil {
		fmt.Println(err)
		return
	}
	movers := []ccxt.Ticker{}
	for _, t := range tickers.Tickers {
		if t.Percentage != nil && t.Symbol != nil {
			movers = append(movers, t)
		}
	}
	sort.Slice(movers, func(i, j int) bool { return *movers[i].Percentage > *movers[j].Percentage })
	n := 10
	if len(movers) < n {
		n = len(movers)
	}
	fmt.Println("Top gainers:")
	for _, t := range movers[:n] {
		fmt.Printf("%s: %.2f%%\n", *t.Symbol, *t.Percentage)
	}
	fmt.Println("Top losers:")
	for i := len(movers) - 1; i >= len(movers)-n; i-- {
		fmt.Printf("%s: %.2f%%\n", *movers[i].Symbol, *movers[i].Percentage)
	}
}
```

