Print the 24h percentage change for the.java:
Fetch all tickers with `fetchTickers`, sort by the `percentage` field and print the 10 biggest gainers and losers.

```java
import io.github.ccxt.types.Ticker;
import java.util.ArrayList;
import java.util.List;
import io.github.ccxt.exchanges.Binance;

public class Main {
    public static void main(String[] args) {
        Binance exchange = new Binance();
        var tickers = exchange.fetchTickers();
        List<Ticker> movers = new ArrayList<>();
        for (Ticker t : tickers.tickers.values()) {
            if (t.percentage != null) {
                movers.add(t);
            }
        }
        movers.sort((a, b) -> Double.compare(b.percentage, a.percentage));
        int n = Math.min(10, movers.size());
        System.out.println("Top gainers:");
        for (int i = 0; i < n; i++) {
            Ticker t = movers.get(i);
            System.out.printf("%s: %.2f%%%n", t.symbol, t.percentage);
        }
        System.out.println("Top losers:");
        for (int i = movers.size() - 1; i >= movers.size() - n; i--) {
            Ticker t = movers.get(i);
            System.out.printf("%s: %.2f%%%n", t.symbol, t.percentage);
        }
    }
}
