Fetch recent trades on bithumb and compu.go:
Fetch recent BTC/KRW trades on bithumb with `fetchTrades`, sum the base volume per `side`, and print the buy/sell ratio.

```go
package main

import (
	"fmt"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func main() {
	exchange := ccxt.NewBithumb(nil)
	trades, err := exchange.FetchTrades("BTC/KRW")
	if err != nil {
		fmt.Println(err)
		return
	}
	buyVolume, sellVolume := 0.0, 0.0
	for _, t := range trades {
		if t.Side == nil || t.Amount == nil {
			continue
		}
		switch *t.Side {
		case "buy":
			buyVolume += *t.Amount
		case "sell":
			sellVolume += *t.Amount
		}
	}
	fmt.Printf("trades: %d, buy volume: %v, sell volume: %v\n", len(trades), buyVolume, sellVolume)
	if sellVolume > 0 {
		fmt.Printf("buy/sell ratio: %.3f\n", buyVolume/sellVolume)
	} else {
		fmt.Println("no sell volume")
	}
}
