Print the top 20 symbols by quote volume.go:
Fetch all tickers with `fetchTickers`, sort them by `quoteVolume` descending and print the top 20.

```go
package main

import (
	"fmt"
	"sort"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func main() {
	exchange := ccxt.NewGate(nil)
	tickers, err := exchange.FetchTickers()
	if err != nil {
		fmt.Println(err)
		return
	}
	list := make([]ccxt.Ticker, 0, len(tickers.Tickers))
	for _, t := range tickers.Tickers {
		list = append(list, t)
	}
	qv := func(t ccxt.Ticker) float64 {
		if t.QuoteVolume == nil {
			return 0
		}
		return *t.QuoteVolume
	}
	sort.Slice(list, func(i, j int) bool { return qv(list[i]) > qv(list[j]) })
	for i := 0; i < len(list) && i < 20; i++ {
		symbol := ""
		if list[i].Symbol != nil {
			symbol = *list[i].Symbol
		}
		fmt.Println(symbol, qv(list[i]))
	}
}
