		fmt.Println(err)
		return
	}
	ranked := []ccxt.Ticker{}
	for _, t := range tickers.Tickers {
		if t.Percentage != nil && t.Symbol != nil {
			ranked = append(ranked, t)
		}
	}
	sort.Slice(ranked, func(i, j int) bool { return *ranked[i].Percentage > *ranked[j].Percentage })
	for i, t := range ranked {
		if i >= 20 {
			break
		}
		fmt.Printf("%s %.2f%%\n", *t.Symbol, *t.Percentage)
	}
}
