Fetch OHLCV for DOGE/USDT on lbank and c.ts:
Fetch 1h candles with `fetchOHLCV` and average the last 20 closes (index 4) to get the 20-period SMA.

```typescript
import ccxt from 'ccxt';

const exchange = new ccxt.lbank();
const period = 20;
const candles = await exchange.fetchOHLCV('DOGE/USDT', '1h', undefined, 100);
const closes = candles.map((c) => Number(c[4] ?? 0));
if (closes.length < period) {
    console.log('not enough candles');
} else {
    const last = closes.slice(-period);
    const sma = last.reduce((a, b) => a + b, 0) / period;
    console.log(`SMA(${period}) = ${sma}`);
}
```

