Fetch canceled orders on kucoin for the.go:
kucoin has no `fetchCanceledOrders`, so fetch closed orders from the last 7 days with `fetchClosedOrders` and keep those whose `status` is `canceled`.

```go
package main

import (
	"fmt"
	"time"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func main() {
	exchange := ccxt.NewKucoin(map[string]interface{}{"apiKey": "YOUR_API_KEY", "secret": "YOUR_SECRET", "password": "YOUR_PASSWORD"})
	since := time.Now().Add(-7 * 24 * time.Hour).UnixMilli()
	orders, err := exchange.FetchClosedOrders(ccxt.WithFetchClosedOrdersSince(since))
	if err != nil {
		fmt.Println(err)
		return
	}
