```go
package main

import (
	"fmt"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func main() {
	exchange := ccxt.NewKraken(map[string]interface{}{"apiKey": "YOUR_API_KEY", "secret": "YOUR_SECRET"})
	orderId := "YOUR_ORDER_ID"
	order, err := exchange.FetchOrder(orderId)
