	for _, t := range order.Trades {
		if t.Id != nil {
			tradeIds = append(tradeIds, *t.Id)
		}
	}
	opts := []ccxt.FetchOrderTradesOptions{ccxt.WithFetchOrderTradesParams(map[string]any{"trades": tradeIds})}
	if order.Symbol != nil {
		opts = append(opts, ccxt.WithFetchOrderTradesSymbol(*order.Symbol))
	}
	trades, err := exchange.FetchOrderTrades(orderId, opts...)
	if err != nil {
		fmt.Println(err)
		return
	}
	for _, trade := range trades {
		id := ""
		if trade.Id != nil {
			id = *trade.Id
		}
		side := ""
		if trade.Side != nil {
			side = *trade.Side
		}
		amount := 0.0
		if trade.Amount != nil {
			amount = *trade.Amount
		}
		price := 0.0
		if trade.Price != nil {
			price = *trade.Price
		}
		fmt.Println(id, side, amount, price)
	}
}
