Fetch the account ledger on okx for the.go:
Call `fetchLedger` with `since` set to 24 hours ago; OKX private calls need `apiKey`, `secret` and the API `password` (passphrase).

```go
package main

import (
	"fmt"
	"time"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func main() {
	exchange := ccxt.NewOkx(map[string]interface{}{"apiKey": "YOUR_API_KEY", "secret": "YOUR_SECRET", "password": "YOUR_PASSWORD"})
	since := time.Now().Add(-24 * time.Hour).UnixMilli()
	ledger, err := exchange.FetchLedger(ccxt.WithFetchLedgerSince(since))
	if err != nil {
		fmt.Println(err)
		return
	}
	for _, entry := range ledger {
		datetime, typ, currency, amount := "", "", "", 0.0
		if entry.Datetime != nil {
			datetime = *entry.Datetime
		}
		if entry.Type != nil {
			typ = *entry.Type
		}
		if entry.Currency != nil {
			currency = *entry.Currency
		}
		if entry.Amount != nil {
			amount = *entry.Amount
		}
		fmt.Println(datetime, typ, amount, currency)
	}
}
```

