```php
<?php
$exchange = new \ccxt\okx(['apiKey' => 'YOUR_API_KEY', 'secret' => 'YOUR_SECRET', 'password' => 'YOUR_PASSWORD']);
$order = $exchange->create_trailing_percent_order('BTC/USDT:USDT', 'market', 'sell', 1, null, 5);
echo $order['id'], ' ', $order['status'], "\n";
```

Create a trailing percent order on bybit.go:
Bybit only supports trailing *amount* orders, so this example uses OKX, which supports `createTrailingPercentOrder`. It places a trailing stop that market-sells 1 contract of `BTC/USDT:USDT` once the price falls 5% from its peak.

```go
package main

import (
	"fmt"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func main() {
	exchange := ccxt.NewOkx(map[string]interface{}{"apiKey": "YOUR_API_KEY", "secret": "YOUR_SECRET", "password": "YOUR_PASSWORD"})
	order, err := exchange.CreateTrailingPercentOrder("BTC/USDT:USDT", "market", "sell", 1, ccxt.WithCreateTrailingPercentOrderTrailingPercent(5))
	if err != nil {
		fmt.Println(err)
		return
	}
	if order.Id != nil {
		fmt.Println("order id:", *order.Id)
	}
}
```

