Create multiple orders in one call on ga.go:
Pass a list of order requests (`symbol`, `type`, `side`, `amount`, `price`) to `createOrders` to submit them in one batch call on Gate.

```go
package main

import (
	"fmt"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func str(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

func main() {
	exchange := ccxt.NewGate(map[string]interface{}{"apiKey": "YOUR_API_KEY", "secret": "YOUR_SECRET"})
	requests := []ccxt.OrderRequest{
		ccxt.NewOrderRequest(map[string]any{"symbol": "BTC/USDT", "type": "limit", "side": "buy", "amount": 0.001, "price": 50000.0}),
		ccxt.NewOrderRequest(map[string]any{"symbol": "BTC/USDT", "type": "limit", "side": "buy", "amount": 0.001, "price": 49000.0}),
	}
	orders, err := exchange.CreateOrders(requests)
	if err != nil {
		fmt.Println(err)
		return
	}
	for _, o := range orders {
		fmt.Println(str(o.Id), str(o.Status))
	}
}
```

