Compute the total portfolio value in USD.ts:
Fetch the balance and all tickers, then value each holding at its `<CODE>/USDT` last price (USDT counts 1:1) and sum; assets without a USDT market are skipped.

```typescript
import ccxt from 'ccxt';

const exchange = new ccxt.binance({ apiKey: 'YOUR_API_KEY', secret: 'YOUR_SECRET' });
const balance = await exchange.fetchBalance();
const tickers = await exchange.fetchTickers();
const skip = new Set(['info', 'timestamp', 'datetime', 'free', 'used', 'total', 'debt']);
let totalValue = 0;
for (const code of Object.keys(balance)) {
    if (skip.has(code)) continue;
    const amount = balance[code].total ?? 0;
    if (amount === 0) continue;
    if (code === 'USDT') {
        totalValue += amount;
        continue;
    }
    const price = tickers[`${code}/USDT`]?.last;
    if (price !== undefined) {
        totalValue += amount * price;
    }
}
console.log(`Portfolio value: ${totalValue.toFixed(2)} USDT`);
```

