Fetch deposits and withdrawals and merge.go:
Call `fetchDeposits` and `fetchWithdrawals` on binance, concatenate the two lists and sort the result by `timestamp` so you get one chronological history (binance has no combined `fetchDepositsWithdrawals`).

```go
package main

import (
	"fmt"
	"sort"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func str(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

func main() {
	exchange := ccxt.NewBinance(map[string]interface{}{"apiKey": "YOUR_API_KEY", "secret": "YOUR_SECRET"})
	deposits, err := exchange.FetchDeposits()
	if err != nil {
		fmt.Println(err)
		return
	}
	withdrawals, err := exchange.FetchWithdrawals()
	if err != nil {
		fmt.Println(err)
		return
	}
	all := append(deposits, withdrawals...)
	ts := func(t ccxt.Transaction) int64 {
		if t.Timestamp == nil {
			return 0
		}
		return *t.Timestamp
	}
	sort.Slice(all, func(i, j int) bool { return ts(all[i]) < ts(all[j]) })
	for _, tx := range all {
		amount := 0.0
		if tx.Amount != nil {
			amount = *tx.Amount
		}
		fmt.Println(str(tx.Datetime), str(tx.Type), str(tx.Currency), amount, str(tx.Status))
	}
}
```

