        List<Transaction> all = new ArrayList<>(exchange.fetchDepositsAsync(null, null, null, null).join());
        all.addAll(exchange.fetchWithdrawalsAsync(null, null, null, null).join());
        all.sort(Comparator.comparingLong(tx -> tx.timestamp != null ? tx.timestamp : 0L));
        for (Transaction tx : all) {
            System.out.println(tx.datetime + " " + tx.type + " " + tx.currency + " " + tx.amount + " " + tx.status);
        }
    }
}
