Withdraw ETH from one exchange to anothe.go:
Get your ETH deposit address on the destination exchange (binance) with `fetchDepositAddress`, then send ETH to it from the source exchange (kucoin) with `withdraw`, pinning the same network on both sides.

```go
package main

import (
	"fmt"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func str(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

func main() {
	source := ccxt.NewKucoin(map[string]interface{}{"apiKey": "YOUR_API_KEY", "secret": "YOUR_SECRET", "password": "YOUR_PASSWORD"})
	destination := ccxt.NewBinance(map[string]interface{}{"apiKey": "YOUR_API_KEY", "secret": "YOUR_SECRET"})
	network := "ERC20"
	amount := 0.05

	deposit, err := destination.FetchDepositAddress("ETH", ccxt.WithFetchDepositAddressParams(map[string]any{"network": network}))
	if err != nil {
		fmt.Println(err)
		return
	}
	address := str(deposit.Address)
	fmt.Println("sending", amount, "ETH to", address)
	params := map[string]any{"network": network}
	if deposit.Tag != nil {
		params["tag"] = *deposit.Tag
	}
	tx, err := source.Withdraw("ETH", amount, address, ccxt.WithWithdrawParams(params))
	if err != nil {
		fmt.Println(err)
		return
	}
	fmt.Println("withdrawal", str(tx.Id), str(tx.Status))
}
