Fetch open orders and cancel the oldest.go:
Fetch open orders with `fetchOpenOrders`, pick the one with the smallest `timestamp`, and cancel it with `cancelOrder`.

```go
package main

import (
	"fmt"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func main() {
	exchange := ccxt.NewMexc(map[string]interface{}{"apiKey": "YOUR_API_KEY", "secret": "YOUR_SECRET"})
	symbol := "BTC/USDT"
	orders, err := exchange.FetchOpenOrders(ccxt.WithFetchOpenOrdersSymbol(symbol))
	if err != nil {
		fmt.Println(err)
		return
	}
	if len(orders) == 0 {
		fmt.Println("No open orders")
		return
	}
	oldest := orders[0]
	for _, o := range orders[1:] {
		if o.Timestamp != nil && (oldest.Timestamp == nil || *o.Timestamp < *oldest.Timestamp) {
			oldest = o
		}
	}
	if oldest.Id == nil {
		fmt.Println("Oldest order has no id")
		return
	}
	fmt.Println("Cancelling", *oldest.Id)
	cancelled, err := exchange.CancelOrder(*oldest.Id, ccxt.WithCancelOrderSymbol(symbol))
	if err != nil {
		fmt.Println(err)
		return
	}
	if cancelled.Status != nil {
		fmt.Println(*cancelled.Status)
	}
}
