Fetch closed orders and compute the real.go:
Fetch closed orders with `fetchClosedOrders` and estimate realized PnL as sell proceeds minus buy cost minus fees (from each order's `cost` and `fee`). This only holds when the window opens and closes flat, because it ignores any position held before it.

```go
package main

import (
	"fmt"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func main() {
	exchange := ccxt.NewBybit(map[string]interface{}{"apiKey": "YOUR_API_KEY", "secret": "YOUR_SECRET"})
	orders, err := exchange.FetchClosedOrders(ccxt.WithFetchClosedOrdersSymbol("BTC/USDT"))
	if err != nil {
		fmt.Println(err)
		return
	}
	pnl := 0.0
	for _, o := range orders {
		cost := 0.0
		if o.Cost != nil {
			cost = *o.Cost
		}
		if o.Side != nil && *o.Side == "sell" {
			pnl += cost
		} else {
			pnl -= cost
		}
		if o.Fee.Cost != nil {
			pnl -= *o.Fee.Cost
		}
	}
	fmt.Printf("Closed orders: %d, realized PnL: %f\n", len(orders), pnl)
}
```

