package main

import (
	"fmt"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func f64(p *float64) float64 {
	if p == nil {
		return 0
	}
	return *p
}

func main() {
	exchange := ccxt.NewDeribit(nil)
	markets, err := exchange.LoadMarkets()
	if err != nil {
		fmt.Println(err)
		return
	}
	count := 0
	for symbol, market := range markets {
		if market.Option == nil || !*market.Option {
