Close an open position with a reduce onl.go:
Look up the open position with `fetchPositions`, then send a market order on the opposite side for the same size with `reduceOnly: true` so it can only close it.

```go
package main

import (
	"fmt"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func main() {
	exchange := ccxt.NewBybit(map[string]interface{}{"apiKey": "YOUR_API_KEY", "secret": "YOUR_SECRET"})
	symbol := "BTC/USDT:USDT"
	positions, err := exchange.FetchPositions(ccxt.WithFetchPositionsSymbols([]string{symbol}))
	if err != nil {
		fmt.Println(err)
		return
	}
	for _, position := range positions {
		if position.Contracts == nil || *position.Contracts == 0 {
			continue
		}
		contracts := *position.Contracts
		positionSide := ""
		if position.Side != nil {
			positionSide = *position.Side
		}
		side := "buy"
		if positionSide == "long" {
			side = "sell"
		}
		order, err := exchange.CreateOrder(symbol, "market", side, contracts, ccxt.WithCreateOrderParams(map[string]interface{}{"reduceOnly": true}))
		if err != nil {
			fmt.Println(err)
			return
		}
		orderId := ""
		if order.Id != nil {
			orderId = *order.Id
		}
		fmt.Println("Closed", positionSide, contracts, "with order", orderId)
	}
}
