Do a margin loan buy sell and repay cycl.go:
Kraken has no explicit borrow/repay endpoints (`borrowMargin`/`repayMargin` are unsupported), so the loan is implicit: a `createOrder` with a `leverage` param opens a margin buy funded by borrowed quote currency, and the opposite `sell` with the same leverage closes the position and repays the loan.

```go
package main

import (
	"fmt"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func str(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

func num(f *float64) float64 {
	if f == nil {
		return 0
	}
	return *f
}

func main() {
	exchange := ccxt.NewKraken(map[string]interface{}{"apiKey": "YOUR_API_KEY", "secret": "YOUR_SECRET"})
	symbol := "ETH/USDT"
	amount := 0.01
	params := map[string]interface{}{"leverage": 2}

	// 1. margin buy: Kraken lends the rest of the USDT needed at 2x
	buy, err := exchange.CreateOrder(symbol, "market", "buy", amount, ccxt.WithCreateOrderParams(params))
	if err != nil {
		fmt.Println(err)
		return
	}
	fmt.Println("margin buy:", str(buy.Id), str(buy.Status))

	// 2. inspect the open margin position (the outstanding loan)
	positions, err := exchange.FetchPositions(ccxt.WithFetchPositionsParams(map[string]interface{}{"docalcs": true}))
	if err != nil {
		fmt.Println(err)
		return
	}
	for _, p := range positions {
		fmt.Println("position:", str(p.Symbol), str(p.Side), num(p.Contracts))
	}

	// 3. sell with the same leverage: closes the position and repays the loan
	sell, err := exchange.CreateOrder(symbol, "market", "sell", amount, ccxt.WithCreateOrderParams(params))
	if err != nil {
		fmt.Println(err)
		return
	}
	fmt.Println("closing sell (repay):", str(sell.Id), str(sell.Status))

	balance, err := exchange.FetchBalance()
	if err != nil {
		fmt.Println(err)
		return
	}
	fmt.Println("USDT total after repay:", num(balance.Total["USDT"]))
}
```

