Reconnect automatically when the websock.ts:
ccxt pro reconnects on the next `watch*` call after the socket drops, so wrap `watchTicker` in a retry loop: on a `NetworkError` wait with exponential backoff and call it again, giving up on any other error.

```typescript
import ccxt from 'ccxt';

const exchange = new ccxt.pro.binance();
const symbol = 'BTC/USDT';
let delay = 1000;

while (true) {
    try {
        const ticker = await exchange.watchTicker(symbol);
        console.log(ticker.datetime, symbol, ticker.last ?? 0);
        delay = 1000;
    } catch (e) {
        if (e instanceof ccxt.NetworkError) {
            console.log(`connection lost (${e.message}), reconnecting in ${delay / 1000}s`);
            await new Promise((resolve) => setTimeout(resolve, delay));
            delay = Math.min(delay * 2, 30000);
        } else {
            console.log('fatal error:', e instanceof Error ? e.message : e);
            break;
        }
    }
