Reconnect automatically when the websock.go:
ccxt pro reconnects on the next `watch*` call after the socket drops, so wrap `watchTicker` in a retry loop: on a `NetworkError` wait with exponential backoff and call it again, giving up on any other error.

```go
package main

import (
	"errors"
	"fmt"
	"time"

	ccxt "github.com/ccxt/ccxt/go/v4"
	ccxtpro "github.com/ccxt/ccxt/go/v4/pro"
)

// NetworkError and its subclasses are the retryable, connection-level failures.
var networkErrors = map[ccxt.ErrorType]bool{
	"NetworkError": true, "DDoSProtection": true, "RateLimitExceeded": true,
	"ExchangeNotAvailable": true, "OnMaintenance": true, "InvalidNonce": true,
	"ChecksumError": true, "RequestTimeout": true,
}

func isNetworkError(err error) bool {
	var e *ccxt.Error
	return errors.As(err, &e) && networkErrors[e.Type]
}

func main() {
	exchange := ccxtpro.NewBinance(nil)
	symbol := "BTC/USDT"
	delay := time.Second
	for {
		ticker, err := exchange.WatchTicker(symbol)
		if err != nil {
			if isNetworkError(err) {
				fmt.Printf("connection lost (%v), reconnecting in %v\n", err, delay)
				time.Sleep(delay)
				if delay < 30*time.Second {
					delay *= 2
				}
				continue
			}
			fmt.Println("fatal error:", err)
			return
		}
		delay = time.Second
		datetime, last := "", 0.0
		if ticker.Datetime != nil {
			datetime = *ticker.Datetime
		}
		if ticker.Last != nil {
			last = *ticker.Last
		}
		fmt.Println(datetime, symbol, last)
	}
}
```

