                if (book.bids.isEmpty() || book.asks.isEmpty()) continue;
                double bestBid = book.bids.get(0).get(0);
                double bestAsk = book.asks.get(0).get(0);
                double spread = bestAsk - bestBid;
                double bps = spread / ((bestAsk + bestBid) / 2) * 10000;
                System.out.printf("%s bid %s ask %s spread %.2f (%.2f bps)%n", symbol, bestBid, bestAsk, spread, bps);
            }
        } catch (Exception e) {
            System.out.println("Error: " + e.getMessage());
        } finally {
            exchange.close().join();
        }
    }
}
