Watch the order book and detect large wa.ts:
Stream the bybit order book with `watchOrderBook` and flag any level whose size is several times the average level size on its side (a "wall").

```typescript
import ccxt from 'ccxt';
import type { Num } from 'ccxt';

const exchange = new ccxt.pro.bybit();
const symbol = 'BTC/USDT';
const depth = 50;
const multiplier = 5; // a wall is a level at least 5x the average size on its side

function findWalls(side: string, levels: [Num, Num][]): void {
    const sizes = levels.map((level) => level[1] ?? 0);
    if (sizes.length === 0) return;
    const average = sizes.reduce((a, b) => a + b, 0) / sizes.length;
    for (const level of levels) {
        const price = level[0] ?? 0;
        const size = level[1] ?? 0;
        if (size >= average * multiplier) {
            console.log(`${side} wall at ${price}: ${size} (${(size / average).toFixed(1)}x avg)`);
        }
    }
}

try {
    while (true) {
        const book = await exchange.watchOrderBook(symbol, depth);
        findWalls('BID', book.bids.slice(0, depth));
        findWalls('ASK', book.asks.slice(0, depth));
    }
} catch (e) {
    console.log('Error:', e);
} finally {
    await exchange.close();
}
