Watch orders and cancel any that stay op.go:
Loop on `watchOrders` for okx, and whenever an update shows an order still `open` longer than a max age (from its `timestamp`), cancel it with `cancelOrder` (private, so dummy keys are used). Note the check only runs when an order update arrives; for a strict timeout, also poll on a timer.

```go
package main

import (
	"fmt"
	"time"

	ccxt "github.com/ccxt/ccxt/go/v4"
	ccxtpro "github.com/ccxt/ccxt/go/v4/pro"
)

const maxAge = 60 * time.Second // cancel orders open longer than 60 seconds

func main() {
	exchange := ccxtpro.NewOkx(map[string]interface{}{"apiKey": "YOUR_API_KEY", "secret": "YOUR_SECRET", "password": "YOUR_PASSWORD"})
	defer exchange.Close()
	cancelled := map[string]bool{}
	for {
		orders, err := exchange.WatchOrders()
		if err != nil {
			fmt.Println("Error:", err)
			return
		}
		now := time.Now().UnixMilli()
		for _, order := range orders {
			if order.Id == nil || order.Status == nil || *order.Status != "open" || cancelled[*order.Id] {
				continue
			}
			ts := now
			if order.Timestamp != nil {
				ts = *order.Timestamp
			}
			age := time.Duration(now-ts) * time.Millisecond
			if age > maxAge {
				symbol := ""
				if order.Symbol != nil {
					symbol = *order.Symbol
				}
				fmt.Printf("Cancelling %s %s open for %s\n", *order.Id, symbol, age.Round(time.Second))
				if _, err := exchange.CancelOrder(*order.Id, ccxt.WithCancelOrderSymbol(symbol)); err != nil {
					fmt.Println("Cancel failed:", err)
					continue
				}
				cancelled[*order.Id] = true
			}
		}
	}
}
