Watch orders and cancel any that stay op.csharp:
Loop on `watchOrders` for okx, and whenever an update shows an order still `open` longer than a max age (from its `timestamp`), cancel it with `cancelOrder` (private, so dummy keys are used). Note the check only runs when an order update arrives; for a strict timeout, also poll on a timer.

```csharp
using ccxt;

var exchange = new ccxt.pro.Okx(new Dictionary<string, object> { { "apiKey", "YOUR_API_KEY" }, { "secret", "YOUR_SECRET" }, { "password", "YOUR_PASSWORD" } });
const long maxAgeMs = 60 * 1000; // cancel orders open longer than 60 seconds
var cancelled = new HashSet<string>();
try
{
    while (true)
    {
        var orders = await exchange.WatchOrders();
        var now = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        foreach (var order in orders)
        {
            if (order.id == null || order.status != "open" || cancelled.Contains(order.id)) continue;
            var age = now - (order.timestamp ?? now);
            if (age > maxAgeMs)
            {
                Console.WriteLine($"Cancelling {order.id} {order.symbol} open for {age / 1000}s");
                await exchange.CancelOrder(order.id, order.symbol);
                cancelled.Add(order.id);
            }
        }
    }
}
catch (Exception e)
{
    Console.WriteLine("Error: " + e.Message);
}
finally
{
    await exchange.Close();
}
