Watch orders and cancel any that stay op.java:
Loop on `watchOrders` for okx, and whenever an update shows an order still `open` longer than a max age (from its `timestamp`), cancel it with `cancelOrder` (private, so dummy keys are used). Note the check only runs when an order update arrives; for a strict timeout, also poll on a timer.

```java
import io.github.ccxt.exchanges.pro.Okx;
import io.github.ccxt.types.Order;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

public class Main {
    static final long MAX_AGE_MS = 60 * 1000; // cancel orders open longer than 60 seconds

    public static void main(String[] args) {
        Map<String, Object> config = new HashMap<>();
        config.put("apiKey", "YOUR_API_KEY");
        config.put("secret", "YOUR_SECRET");
        config.put("password", "YOUR_PASSWORD");
        Okx exchange = new Okx(config);
        Set<String> cancelled = new HashSet<>();
        try {
            while (true) {
                List<Order> orders = exchange.watchOrders();
                long now = System.currentTimeMillis();
                for (Order order : orders) {
                    if (order.id == null || !"open".equals(order.status) || cancelled.contains(order.id)) continue;
                    long age = now - (order.timestamp != null ? order.timestamp : now);
                    if (age > MAX_AGE_MS) {
                        System.out.println("Cancelling " + order.id + " " + order.symbol + " open for " + (age / 1000) + "s");
                        exchange.cancelOrder(order.id, order.symbol);
                        cancelled.add(order.id);
                    }
                }
            }
        } catch (Exception e) {
            System.out.println("Error: " + e.getMessage());
        } finally {
            exchange.close().join();
        }
    }
}
```

