Watch ticker and ohlcv on bitmex at the.go:
BitMEX isn't available in every language's installed ccxt, so this uses bybit's perpetual `BTC/USDT:USDT` instead: run `watchTicker` and `watchOHLCV` concurrently over WebSockets and print each update as it arrives.

```go
package main

import (
	"fmt"
	"sync"

	ccxt "github.com/ccxt/ccxt/go/v4"
	ccxtpro "github.com/ccxt/ccxt/go/v4/pro"
)

func main() {
	exchange := ccxtpro.NewBybit(nil)
	symbol := "BTC/USDT:USDT"
	var wg sync.WaitGroup
	wg.Add(2)

	go func() {
		defer wg.Done()
		for i := 0; i < 10; i++ {
			ticker, err := exchange.WatchTicker(symbol)
			if err != nil {
				fmt.Println("ticker error:", err)
				return
			}
			last := 0.0
			if ticker.Last != nil {
				last = *ticker.Last
			}
			datetime := ""
			if ticker.Datetime != nil {
				datetime = *ticker.Datetime
			}
			fmt.Println("ticker", datetime, "last", last)
		}
	}()

	go func() {
		defer wg.Done()
		for i := 0; i < 10; i++ {
			candles, err := exchange.WatchOHLCV(symbol, ccxt.WithWatchOHLCVTimeframe("1m"))
			if err != nil {
				fmt.Println("ohlcv error:", err)
				return
			}
			if len(candles) == 0 {
				continue
			}
			c := candles[len(candles)-1]
			fmt.Println("ohlcv", c.Timestamp, "O", c.Open, "H", c.High, "L", c.Low, "C", c.Close, "V", c.Volume)
		}
	}()

	wg.Wait()
	exchange.Close()
}
