Watch trades on cryptocom and aggregate.ts:
Stream cryptocom trades with `watchTrades` (only new trades per call) and fold them into 1-minute OHLCV bars keyed by `floor(timestamp / 60000)`. A bar is printed once a trade from the next minute arrives.

```typescript
import ccxt from 'ccxt';

type Bar = { open: number; high: number; low: number; close: number; volume: number };

const exchange = new ccxt.pro.cryptocom();
const symbol = 'BTC/USDT';
const bars = new Map<number, Bar>();
let current: number | undefined;

for (let i = 0; i < 200; i++) {
    const trades = await exchange.watchTrades(symbol);
    for (const t of trades) {
        if (t.timestamp === undefined || t.price === undefined || t.amount === undefined) continue;
        const minute = Math.floor(t.timestamp / 60000) * 60000;
        const bar = bars.get(minute);
        if (bar === undefined) {
            bars.set(minute, { open: t.price, high: t.price, low: t.price, close: t.price, volume: t.amount });
        } else {
            bar.high = Math.max(bar.high, t.price);
            bar.low = Math.min(bar.low, t.price);
            bar.close = t.price;
            bar.volume += t.amount;
        }
        if (current !== undefined && minute > current) {
            const done = bars.get(current);
            if (done !== undefined) {
                console.log(new Date(current).toISOString(), 'O', done.open, 'H', done.high, 'L', done.low, 'C', done.close, 'V', done.volume.toFixed(6));
            }
        }
        if (current === undefined || minute > current) current = minute;
    }
}
await exchange.close();
```

