Watch trades on cryptocom and aggregate.go:
Stream cryptocom trades with `watchTrades` (only new trades per call) and fold them into 1-minute OHLCV bars keyed by `floor(timestamp / 60000)`. A bar is printed once a trade from the next minute arrives.

```go
package main

import (
	"fmt"
	"math"
	"time"

	ccxtpro "github.com/ccxt/ccxt/go/v4/pro"
)

type bar struct {
	open, high, low, close, volume float64
}

func main() {
	exchange := ccxtpro.NewCryptocom(nil)
	defer exchange.Close()
	symbol := "BTC/USDT"
	bars := map[int64]*bar{}
	var current int64 = -1

	for i := 0; i < 200; i++ {
		trades, err := exchange.WatchTrades(symbol)
		if err != nil {
			fmt.Println(err)
			return
		}
		for _, t := range trades {
			if t.Timestamp == nil || t.Price == nil || t.Amount == nil {
				continue
			}
			minute := *t.Timestamp / 60000 * 60000
			p, a := *t.Price, *t.Amount
			if b, ok := bars[minute]; ok {
				b.high = math.Max(b.high, p)
				b.low = math.Min(b.low, p)
				b.close = p
				b.volume += a
			} else {
				bars[minute] = &bar{p, p, p, p, a}
			}
			if current >= 0 && minute > current {
				b := bars[current]
				fmt.Println(time.UnixMilli(current).UTC().Format(time.RFC3339), "O", b.open, "H", b.high, "L", b.low, "C", b.close, "V", fmt.Sprintf("%.6f", b.volume))
			}
			if minute > current {
				current = minute
			}
		}
	}
}
