Handle a graceful shutdown while watchin.ts:
Watch several okx order books until Ctrl+C/SIGTERM (or a 30 s deadline), then stop the loops and call `close()` so the WebSocket connections shut down cleanly.

```typescript
import ccxt from 'ccxt';

const exchange = new ccxt.pro.okx();
const symbols = ['BTC/USDT', 'ETH/USDT'];
let running = true;

const stop = (reason: string) => {
    if (running) {
        console.log('shutting down:', reason);
        running = false;
    }
};
process.once('SIGINT', () => stop('SIGINT'));
process.once('SIGTERM', () => stop('SIGTERM'));
const deadline = setTimeout(() => stop('deadline'), 30_000);

async function watch(symbol: string): Promise<void> {
    while (running) {
        try {
            const ob = await exchange.watchOrderBook(symbol);
            console.log(symbol, 'bid', ob.bids[0]?.[0] ?? 'n/a', 'ask', ob.asks[0]?.[0] ?? 'n/a');
        } catch (e) {
            if (running) console.log(symbol, 'error', e instanceof Error ? e.message : String(e));
        }
    }
}

const loops = Promise.all(symbols.map(watch));
while (running) {
    await new Promise((resolve) => setTimeout(resolve, 100));
}
await exchange.close(); // closes sockets; pending watchers reject and their loops exit
await loops;
clearTimeout(deadline);
console.log('closed cleanly');
```

