Handle a graceful shutdown while watchin.go:
Watch several okx order books until Ctrl+C/SIGTERM (or a 30 s deadline), then stop the loops and call `close()` so the WebSocket connections shut down cleanly.

```go
package main

import (
	"context"
	"fmt"
	"os"
	"os/signal"
	"sync"
	"syscall"
	"time"

	ccxtpro "github.com/ccxt/ccxt/go/v4/pro"
)

func main() {
	exchange := ccxtpro.NewOkx(nil)
	symbols := []string{"BTC/USDT", "ETH/USDT"}

	ctx, cancel := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer cancel()
	ctx, cancelTimeout := context.WithTimeout(ctx, 30*time.Second)
	defer cancelTimeout()

	var wg sync.WaitGroup
	for _, symbol := range symbols {
		wg.Add(1)
		go func(symbol string) {
			defer wg.Done()
			for ctx.Err() == nil {
				ob, err := exchange.WatchOrderBook(symbol)
				if err != nil {
					if ctx.Err() == nil {
						fmt.Println(symbol, "error", err)
					}
					continue
				}
				bid, ask := "n/a", "n/a"
				if len(ob.Bids) > 0 {
					bid = fmt.Sprint(ob.Bids[0][0])
				}
				if len(ob.Asks) > 0 {
					ask = fmt.Sprint(ob.Asks[0][0])
				}
				fmt.Println(symbol, "bid", bid, "ask", ask)
			}
		}(symbol)
	}

	<-ctx.Done()
