Handle a graceful shutdown while watchin.java:
Watch several okx order books until Ctrl+C/SIGTERM (or a 30 s deadline), then stop the loops and call `close()` so the WebSocket connections shut down cleanly.

```java
import io.github.ccxt.exchanges.pro.Okx;
import io.github.ccxt.types.OrderBook;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

public class Main {
    public static void main(String[] args) throws InterruptedException {
        Okx exchange = new Okx();
        List<String> symbols = List.of("BTC/USDT", "ETH/USDT");
        AtomicBoolean running = new AtomicBoolean(true);
        CountDownLatch stopped = new CountDownLatch(1);

        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            running.set(false);
            exchange.close().join();
        }));

        List<CompletableFuture<Void>> loops = new ArrayList<>();
        for (String symbol : symbols) {
            loops.add(CompletableFuture.runAsync(() -> {
                while (running.get()) {
                    try {
                        OrderBook ob = exchange.watchOrderBook(symbol);
                        Object bid = ob.bids.isEmpty() ? "n/a" : ob.bids.get(0).get(0);
                        Object ask = ob.asks.isEmpty() ? "n/a" : ob.asks.get(0).get(0);
                        System.out.println(symbol + " bid " + bid + " ask " + ask);
                    } catch (Exception e) {
                        if (running.get()) System.out.println(symbol + " error " + e.getMessage());
                    }
                }
            }));
        }

        stopped.await(30, TimeUnit.SECONDS); // deadline (Ctrl+C triggers the shutdown hook)
        System.out.println("shutting down");
        running.set(false);
        exchange.close().join(); // closes sockets so blocked watchers return
        CompletableFuture.allOf(loops.toArray(new CompletableFuture[0])).join();
        System.out.println("closed cleanly");
        System.exit(0);
    }
}
```

