import io.github.ccxt.exchanges.pro.Binance;
import io.github.ccxt.types.OrderBook;
import io.github.ccxt.types.Ticker;
import io.github.ccxt.types.Trade;
import java.util.List;
import java.util.concurrent.CompletableFuture;

public class Main {
    static final String SYMBOL = "BTC/USDT";
    static final int UPDATES = 5;

    public static void main(String[] args) {
        Binance exchange = new Binance();

        CompletableFuture<Void> tickerLoop = CompletableFuture.runAsync(() -> {
            for (int i = 0; i < UPDATES; i++) {
                // ccxt.pro watch* methods return CompletableFuture, so join() waits for the next update
                Ticker ticker = exchange.watchTicker(SYMBOL, null).join();
                System.out.println("ticker " + ticker.symbol + " " + ticker.last);
            }
        });

        CompletableFuture<Void> bookLoop = CompletableFuture.runAsync(() -> {
            for (int i = 0; i < UPDATES; i++) {
                OrderBook book = exchange.watchOrderBook(SYMBOL, null, null).join();
                Double bid = book.bids.isEmpty() ? null : book.bids.get(0).get(0);
                Double ask = book.asks.isEmpty() ? null : book.asks.get(0).get(0);
                System.out.println("book " + book.symbol + " bid " + bid + " ask " + ask);
            }
        });

        CompletableFuture<Void> tradesLoop = CompletableFuture.runAsync(() -> {
            for (int i = 0; i < UPDATES; i++) {
                List<Trade> trades = exchange.watchTrades(SYMBOL, null, null, null).join();
                if (!trades.isEmpty()) {
                    Trade last = trades.get(trades.size() - 1);
                    System.out.println("trades " + trades.size() + " last " + last.price + " " + last.amount);
                }
            }
        });

        CompletableFuture.allOf(tickerLoop, bookLoop, tradesLoop).join();
