Fetch an event on polymarket and then fe.go:
Find an event with `fetchEvents` (scoped by `query`), re-fetch it by id with `fetchEvent`, then pass the first unresolved market's outcome handle (`outcome.outcome`) to `fetchTicker`; the price is the market-implied probability.

```go
package main

import (
	"fmt"

	ccxt "github.com/ccxt/ccxt/go/v4"
	ccxtprediction "github.com/ccxt/ccxt/go/v4/prediction"
)

func str(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

func num(f *float64) string {
	if f == nil {
		return "n/a"
	}
	return fmt.Sprint(*f)
}

func main() {
	exchange := ccxtprediction.NewPolymarket(nil)
	found, err := exchange.FetchEvents(map[string]interface{}{"query": "bitcoin", "sort": "volume", "limit": 1})
	if err != nil {
		fmt.Println(err)
		return
	}
	if len(found) == 0 || found[0].Id == nil {
		fmt.Println("no event found")
		return
	}
	event, err := exchange.FetchEvent(*found[0].Id)
	if err != nil {
		fmt.Println(err)
		return
	}
	fmt.Println("event:", str(event.Id), str(event.Title))
	var market *ccxt.PredictionMarket
	for i := range event.Markets {
		m := &event.Markets[i]
		if (m.Resolved == nil || !*m.Resolved) && len(m.Outcomes) > 0 {
			market = m
			break
		}
	}
	if market == nil || market.Outcomes[0].Outcome == nil {
		fmt.Println("no open market with outcomes in this event")
		return
	}
	outcome := market.Outcomes[0]
	ticker, err := exchange.FetchTicker(*outcome.Outcome)
	if err != nil {
		fmt.Println("FetchTicker failed:", err)
		return
	}
	fmt.Println("market:", str(market.Title))
	fmt.Println("outcome:", str(outcome.Label), "last:", num(ticker.Last), "bid:", num(ticker.Bid), "ask:", num(ticker.Ask))
}
