```java
import io.github.ccxt.exchanges.prediction.Polymarket;
import io.github.ccxt.types.PredictionEvent;
import io.github.ccxt.types.PredictionMarket;
import io.github.ccxt.types.PredictionOutcome;
import io.github.ccxt.types.PredictionTicker;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Main {
    public static void main(String[] args) {
        Polymarket exchange = new Polymarket();
        Map<String, Object> params = new HashMap<>();
        params.put("query", "bitcoin");
        params.put("sort", "volume");
        params.put("limit", 1);
        // prediction-exchange methods return CompletableFuture; join() waits for the result
        List<PredictionEvent> found = exchange.fetchEvents(params).join();
        if (found.isEmpty() || found.get(0).id == null) {
            System.out.println("no event found");
            return;
        }
        PredictionEvent event = exchange.fetchEvent(found.get(0).id, new HashMap<>()).join();
        System.out.println("event: " + event.id + " " + event.title);
        PredictionMarket market = null;
        if (event.markets != null) {
            for (PredictionMarket m : event.markets) {
                if (!Boolean.TRUE.equals(m.resolved) && m.outcomes != null && !m.outcomes.isEmpty()) {
                    market = m;
                    break;
                }
            }
        }
        if (market == null || market.outcomes.get(0).outcome == null) {
            System.out.println("no open market with outcomes in this event");
            return;
        }
        PredictionOutcome outcome = market.outcomes.get(0);
        try {
            PredictionTicker ticker = exchange.fetchTicker(outcome.outcome, new HashMap<>()).join();
            System.out.println("market: " + market.title);
            System.out.println("outcome: " + outcome.label + " last: " + ticker.last + " bid: " + ticker.bid + " ask: " + ticker.ask);
        } catch (Exception e) {
            System.out.println("fetchTicker failed: " + e.getMessage());
