Compare the implied probability of yes a.go:
An outcome's price is its market-implied probability: find an open binary Polymarket market, fetch the ticker for its Yes and No outcomes, and compare the two prices (they should sum to roughly 1).

```go
package main

import (
	"fmt"

	ccxt "github.com/ccxt/ccxt/go/v4"
	ccxtprediction "github.com/ccxt/ccxt/go/v4/prediction"
)

func prob(t ccxt.PredictionTicker, o ccxt.PredictionOutcome) float64 {
	if t.Last != nil {
		return *t.Last
	}
	if o.Price != nil {
		return *o.Price
	}
	return 0
}

func label(o ccxt.PredictionOutcome, fallback string) string {
	if o.Label != nil {
		return *o.Label
	}
	return fallback
}

func main() {
	exchange := ccxtprediction.NewPolymarket(nil)
	events, err := exchange.FetchEvents(map[string]interface{}{"query": "bitcoin", "limit": 5})
	if err != nil {
		fmt.Println(err)
		return
	}
	for _, event := range events {
		for _, market := range event.Markets {
			outcomes := market.Outcomes
			if (market.Resolved != nil && *market.Resolved) || len(outcomes) != 2 || outcomes[0].Outcome == nil || outcomes[1].Outcome == nil {
				continue
			}
			yes, err := exchange.FetchTicker(*outcomes[0].Outcome)
			if err != nil {
				continue
			}
			no, err := exchange.FetchTicker(*outcomes[1].Outcome)
			if err != nil {
				continue
			}
			pYes := prob(yes, outcomes[0])
			pNo := prob(no, outcomes[1])
			if market.Title != nil {
				fmt.Println(*market.Title)
			}
			fmt.Printf("%s: %.1f%%\n", label(outcomes[0], "Yes"), pYes*100)
			fmt.Printf("%s: %.1f%%\n", label(outcomes[1], "No"), pNo*100)
			fmt.Printf("Sum: %.1f%% (overround %.1f%%)\n", (pYes+pNo)*100, (pYes+pNo-1)*100)
			return
		}
	}
}
