Fetch OHLCV history for a polymarket out.go:
Find an open Polymarket market with `fetchEvents`, take an outcome's `.outcome` handle and pass it to `fetchOHLCV` — candle prices are implied probabilities (0..1).

```go
package main

import (
	"fmt"
	"time"

	ccxt "github.com/ccxt/ccxt/go/v4"
	ccxtprediction "github.com/ccxt/ccxt/go/v4/prediction"
)

func main() {
	exchange := ccxtprediction.NewPolymarket(nil)
	events, err := exchange.FetchEvents(map[string]interface{}{"query": "bitcoin", "limit": 5})
	if err != nil {
		fmt.Println(err)
		return
	}
	symbol := ""
	for _, event := range events {
		for _, market := range event.Markets {
			if (market.Resolved != nil && *market.Resolved) || len(market.Outcomes) == 0 || market.Outcomes[0].Outcome == nil {
				continue
			}
			symbol = *market.Outcomes[0].Outcome
			title, label := "", ""
			if event.Title != nil {
				title = *event.Title
			}
			if market.Outcomes[0].Label != nil {
				label = *market.Outcomes[0].Label
			}
			fmt.Println("Event:", title, "| outcome:", label)
			break
		}
		if symbol != "" {
			break
		}
	}
	if symbol == "" {
		fmt.Println("No open market found")
		return
	}
	ohlcv, err := exchange.FetchOHLCV(symbol, ccxt.WithFetchOHLCVTimeframe("1h"), ccxt.WithFetchOHLCVLimit(24))
	if err != nil {
		fmt.Println(err)
		return
	}
	for _, c := range ohlcv {
		fmt.Println(time.UnixMilli(c.Timestamp).UTC().Format(time.RFC3339), c.Open, c.High, c.Low, c.Close, c.Volume)
	}
}
