			if market.Resolved != nil && *market.Resolved {
				continue
			}
			prices := []string{}
			for _, o := range market.Outcomes {
				p := 0.0
				if o.Price != nil {
					p = *o.Price
				}
				prices = append(prices, fmt.Sprintf("%s=%.1f%%", str(o.Label), p*100))
			}
			fmt.Printf("  %s: %s\n", str(market.Title), strings.Join(prices, ", "))
		}
	}
}

