```go
package main

import (
	"fmt"

	ccxtprediction "github.com/ccxt/ccxt/go/v4/prediction"
)

func num(f *float64) string {
	if f == nil {
		return "n/a"
	}
	return fmt.Sprint(*f)
}

func main() {
	exchange := ccxtprediction.NewMyriad(nil)
	events, err := exchange.FetchEvents(map[string]interface{}{"query": "bitcoin", "limit": 5})
	if err != nil {
		fmt.Println(err)
		return
	}
	outcomes := []string{}
	for _, event := range events {
		for _, market := range event.Markets {
			if market.Resolved != nil && *market.Resolved {
				continue
			}
			for _, outcome := range market.Outcomes {
				if outcome.Outcome != nil {
					outcomes = append(outcomes, *outcome.Outcome)
				}
			}
		}
	}
	if len(outcomes) == 0 {
		fmt.Println("No open outcomes found")
		return
	}
	if len(outcomes) > 10 {
		outcomes = outcomes[:10]
	}
	tickers, err := exchange.FetchTickers(ccxtprediction.WithFetchTickersOutcomes(outcomes))
	if err != nil {
		fmt.Println(err)
		return
	}
	for symbol, ticker := range tickers.Tickers {
		label := ""
		if ticker.Label != nil {
			label = *ticker.Label
		}
		fmt.Println(symbol, label, "last:", num(ticker.Last), "bid:", num(ticker.Bid), "ask:", num(ticker.Ask))
	}
}
