```go
package main

import (
	"fmt"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func main() {
	type venue struct {
		name  string
		fetch func(string) (ccxt.Ticker, error)
	}
	binance := ccxt.NewBinance(nil)
	bybit := ccxt.NewBybit(nil)
	okx := ccxt.NewOkx(nil)
	venues := []venue{
		{"binance", func(s string) (ccxt.Ticker, error) { return binance.FetchTicker(s) }},
		{"bybit", func(s string) (ccxt.Ticker, error) { return bybit.FetchTicker(s) }},
		{"okx", func(s string) (ccxt.Ticker, error) { return okx.FetchTicker(s) }},
	}
	prices := map[string]float64{}
	for _, v := range venues {
		ticker, err := v.fetch("BTC/USDT")
		if err != nil {
			fmt.Printf("%s: error %v\n", v.name, err)
			continue
		}
		if ticker.Last != nil {
			prices[v.name] = *ticker.Last
			fmt.Printf("%s: %v\n", v.name, *ticker.Last)
		}
	}
	if len(prices) > 1 {
		first := true
		var low, high float64
		for _, p := range prices {
			if first || p < low {
				low = p
			}
			if first || p > high {
				high = p
			}
			first = false
		}
		fmt.Printf("spread: %.2f (%.4f%%)\n", high-low, (high-low)/low*100)
	}
}
