		if err != nil {
			fmt.Printf("%s: %v\n", id, err)
			continue
		}
		for _, symbol := range symbols {
			ticker, ok := tickers.Tickers[symbol]
			if !ok {
				continue
			}
			bid, ask := val(ticker.Bid), val(ticker.Ask)
			if bid <= 0 || ask <= 0 {
				continue
			}
			bps := (ask - bid) / ((ask + bid) / 2) * 10000
			fmt.Printf("%-8s %-10s bid %v ask %v spread %.2f bps\n", id, symbol, bid, ask, bps)
			if bps > widestBps {
				widestVenue, widestSymbol, widestBps = id, symbol, bps
			}
		}
	}
