```typescript
import ccxt from 'ccxt';
import type { Exchange } from 'ccxt';

const symbol = 'BTC/USDT';
const exchanges: Exchange[] = [new ccxt.binance(), new ccxt.okx(), new ccxt.bybit(), new ccxt.kucoin(), new ccxt.gate()];

const rows: { id: string; bid: number; ask: number }[] = [];
for (const exchange of exchanges) {
    try {
        const ticker = await exchange.fetchTicker(symbol);
        rows.push({ id: exchange.id, bid: ticker.bid ?? 0, ask: ticker.ask ?? 0 });
    } catch (e) {
        console.log(`${exchange.id}: ${(e as Error).message}`);
    }
}
console.log('exchange        bid             ask');
for (const r of rows) {
    console.log(`${r.id.padEnd(10)} ${r.bid.toFixed(2).padStart(14)} ${r.ask.toFixed(2).padStart(14)}`);
}
const valid = rows.filter((r) => r.bid > 0 && r.ask > 0);
if (valid.length > 1) {
    const buy = valid.reduce((a, b) => (b.ask < a.ask ? b : a));
    const sell = valid.reduce((a, b) => (b.bid > a.bid ? b : a));
    const pct = (sell.bid - buy.ask) / buy.ask * 100;
    console.log(`Buy on ${buy.id} at ${buy.ask}, sell on ${sell.id} at ${sell.bid}: ${pct.toFixed(3)}% gross`);
}
