Fetch tickers from many exchanges concur.go:
Start every `fetchTicker` call at once and wait for all of them with `Promise.all` (each failure is caught so one bad exchange doesn't reject the batch); the other languages use their native equivalent — a thread pool in Python, ccxt's async classes with ReactPHP's `all()` in PHP, goroutines in Go, `Task.WhenAll` in C# and `CompletableFuture.allOf` in Java.

```go
package main

import (
	"fmt"
	"sync"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func main() {
	symbol := "BTC/USDT"
	ids := []string{"binance", "okx", "bybit", "kucoin", "gate"}

	results := make([]string, len(ids))
	var wg sync.WaitGroup
	for i, id := range ids {
		wg.Add(1)
		go func(i int, id string) {
			defer wg.Done()
			exchange := ccxt.CreateExchange(id, nil)
			ticker, err := exchange.FetchTicker(symbol)
			if err != nil {
				results[i] = fmt.Sprintf("%-10s error: %v", id, err)
				return
			}
			last := 0.0
			if ticker.Last != nil {
				last = *ticker.Last
			}
			results[i] = fmt.Sprintf("%-10s last %v", id, last)
		}(i, id)
	}
	wg.Wait()
	for _, line := range results {
		fmt.Println(line)
	}
}
```

