```java
import io.github.ccxt.Exchange;
import io.github.ccxt.exchanges.Binance;
import io.github.ccxt.exchanges.Bybit;
import io.github.ccxt.exchanges.Gate;
import io.github.ccxt.exchanges.Kucoin;
import io.github.ccxt.exchanges.Okx;
import java.util.List;
import java.util.concurrent.CompletableFuture;

public class Main {
    public static void main(String[] args) {
        String symbol = "BTC/USDT";
        List<Exchange> exchanges = List.of(new Binance(), new Okx(), new Bybit(), new Kucoin(), new Gate());

        List<CompletableFuture<String>> futures = exchanges.stream()
            .map(exchange -> exchange.fetchTickerAsync(symbol)
                .thenApply(ticker -> String.format("%-10s last %s", exchange.id, ticker.last))
                .exceptionally(e -> String.format("%-10s error: %s", exchange.id, e.getMessage())))
            .toList();
        CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).join();
        for (CompletableFuture<String> future : futures) {
            System.out.println(future.join());
        }
    }
}
