        }

        String highest = null;
        String lowest = null;
        for (Map.Entry<String, Double> entry : rates.entrySet()) {
            if (highest == null || entry.getValue() > rates.get(highest)) highest = entry.getKey();
            if (lowest == null || entry.getValue() < rates.get(lowest)) lowest = entry.getKey();
