Fetch balances from binance kucoin and o.go:
Create binance, kucoin and okx with dummy credentials (kucoin and okx also need an API `password`) and fetch all three balances concurrently, then print the non-zero totals.

```go
package main

import (
	"fmt"
	"sync"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

type result struct {
	id      string
	balance ccxt.Balances
	err     error
}

func main() {
	exchanges := []ccxt.IExchange{
		ccxt.NewBinance(map[string]interface{}{"apiKey": "YOUR_API_KEY", "secret": "YOUR_SECRET"}),
		ccxt.NewKucoin(map[string]interface{}{"apiKey": "YOUR_API_KEY", "secret": "YOUR_SECRET", "password": "YOUR_PASSWORD"}),
		ccxt.NewOkx(map[string]interface{}{"apiKey": "YOUR_API_KEY", "secret": "YOUR_SECRET", "password": "YOUR_PASSWORD"}),
	}

	results := make([]result, len(exchanges))
	var wg sync.WaitGroup
	for i, exchange := range exchanges {
		wg.Add(1)
		go func(i int, exchange ccxt.IExchange) {
			defer wg.Done()
			balance, err := exchange.FetchBalance()
			results[i] = result{exchange.GetId(), balance, err}
		}(i, exchange)
	}
	wg.Wait()

	for _, r := range results {
		if r.err != nil {
			fmt.Println(r.id, "error:", r.err)
			continue
		}
		for currency, amount := range r.balance.Total {
			if amount != nil && *amount != 0 {
				fmt.Printf("%s %s: %v\n", r.id, currency, *amount)
			}
		}
	}
}
