Find the widest bid ask spread among ten.ts:
Fetch the BTC/USDT ticker on ten exchanges, compute the relative bid/ask spread `(ask - bid) / mid` for each, and report the widest one.

```typescript
import ccxt from 'ccxt';

const symbol = 'BTC/USDT';
const exchanges = [
    new ccxt.binance(), new ccxt.bybit(), new ccxt.okx(), new ccxt.kucoin(), new ccxt.gate(),
    new ccxt.mexc(), new ccxt.bitget(), new ccxt.htx(), new ccxt.cryptocom(), new ccxt.kraken(),
];

let widestId = '';
let widestSpread = -1;

for (const exchange of exchanges) {
    try {
        const ticker = await exchange.fetchTicker(symbol);
        const bid = ticker.bid ?? 0;
        const ask = ticker.ask ?? 0;
        if (bid <= 0 || ask <= 0) {
            continue;
        }
        const spread = (ask - bid) / ((ask + bid) / 2);
        console.log(`${exchange.id.padEnd(10)} bid ${bid}  ask ${ask}  spread ${(spread * 100).toFixed(4)}%`);
        if (spread > widestSpread) {
            widestSpread = spread;
            widestId = exchange.id;
        }
    } catch (e) {
        console.log(`${exchange.id.padEnd(10)} error`);
    }
}

console.log(`widest spread: ${widestId} (${(widestSpread * 100).toFixed(4)}%)`);
