```go
package main

import (
	"fmt"
	"time"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func main() {
	symbol := "BTC/USDT"
	binance := ccxt.NewBinance(nil)
	bybit := ccxt.NewBybit(nil)

	binanceCandles, err := binance.FetchOHLCV(symbol, ccxt.WithFetchOHLCVTimeframe("1h"), ccxt.WithFetchOHLCVLimit(10))
	if err != nil {
		fmt.Println("binance error:", err)
		return
	}
	bybitCandles, err := bybit.FetchOHLCV(symbol, ccxt.WithFetchOHLCVTimeframe("1h"), ccxt.WithFetchOHLCVLimit(10))
	if err != nil {
		fmt.Println("bybit error:", err)
		return
	}

	bybitCloses := map[int64]float64{}
	for _, candle := range bybitCandles {
		bybitCloses[candle.Timestamp] = candle.Close
	}

	fmt.Println("time                      binance      bybit       diff")
	for _, candle := range binanceCandles {
		bybitClose, ok := bybitCloses[candle.Timestamp]
		if !ok {
			continue
		}
		t := time.UnixMilli(candle.Timestamp).UTC().Format(time.RFC3339)
		fmt.Printf("%-24s  %10.2f %10.2f %10.2f\n", t, candle.Close, bybitClose, candle.Close-bybitClose)
	}
}
