console.log(`mexc: ${mexcPrice}`);
console.log(`divergence: ${diffPct.toFixed(4)}%`);
if (diffPct > threshold) {
    const cheaper = htxPrice < mexcPrice ? 'htx' : 'mexc';
    console.log(`DIVERGENCE above ${threshold}% - buy on ${cheaper}, sell on the other`);
} else {
    console.log('Prices are in line');
}
