Fetch OHLCV from many exchanges continuo.ts:
Poll `fetchOHLCV` for `BTC/USDT` 1m candles on binance, okx, kraken and bybit in a loop (3 rounds here, raise it to run longer), and merge candles with the same timestamp into one series with the average close and total volume.

```typescript
import ccxt from 'ccxt';

const symbol = 'BTC/USDT';
const timeframe = '1m';
const rounds = 3;
const exchanges = [new ccxt.binance(), new ccxt.okx(), new ccxt.kraken(), new ccxt.bybit()];

// timestamp -> { closes, volume }
const merged = new Map<number, { closes: number[]; volume: number }>();

for (let round = 1; round <= rounds; round++) {
    const results = await Promise.allSettled(exchanges.map((ex) => ex.fetchOHLCV(symbol, timeframe, undefined, 5)));
    results.forEach((res, i) => {
        if (res.status === 'rejected') {
            console.log(`${exchanges[i].id}: ${String(res.reason).slice(0, 80)}`);
            return;
        }
        for (const [ts, , , , close, volume] of res.value) {
            if (ts === undefined || close === undefined) continue;
            const entry = merged.get(ts) ?? { closes: [], volume: 0 };
            entry.closes.push(close);
            entry.volume += volume ?? 0;
            merged.set(ts, entry);
        }
    });
    console.log(`--- round ${round} ---`);
    const keys = [...merged.keys()].sort((a, b) => a - b).slice(-5);
    for (const ts of keys) {
        const e = merged.get(ts)!;
        const avg = e.closes.reduce((s, c) => s + c, 0) / e.closes.length;
        console.log(`${new Date(ts).toISOString()} avgClose=${avg.toFixed(2)} volume=${e.volume.toFixed(4)} sources=${e.closes.length}`);
    }
    merged.clear(); // start each round fresh so sources are not double-counted
    if (round < rounds) await new Promise((r) => setTimeout(r, 10000));
}
```

