Fetch OHLCV from many exchanges continuo.go:
Poll `fetchOHLCV` for `BTC/USDT` 1m candles on binance, okx, kraken and bybit in a loop (3 rounds here, raise it to run longer), and merge candles with the same timestamp into one series with the average close and total volume.

```go
package main

import (
	"fmt"
	"sort"
	"time"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

type bucket struct {
	sumClose float64
	count    int
	volume   float64
}

func main() {
	symbol := "BTC/USDT"
	timeframe := "1m"
	rounds := 3
	ids := []string{"binance", "okx", "kraken", "bybit"}
	exchanges := []ccxt.IExchange{}
	for _, id := range ids {
		exchanges = append(exchanges, ccxt.CreateExchange(id, nil))
	}

	for round := 1; round <= rounds; round++ {
		merged := map[int64]*bucket{}
		for i, exchange := range exchanges {
			candles, err := exchange.FetchOHLCV(symbol, ccxt.WithFetchOHLCVTimeframe(timeframe), ccxt.WithFetchOHLCVLimit(5))
			if err != nil {
				fmt.Printf("%s: %v\n", ids[i], err)
				continue
			}
			for _, c := range candles {
				b, ok := merged[c.Timestamp]
				if !ok {
					b = &bucket{}
					merged[c.Timestamp] = b
				}
				b.sumClose += c.Close
				b.count++
				b.volume += c.Volume
			}
		}
		keys := make([]int64, 0, len(merged))
		for ts := range merged {
			keys = append(keys, ts)
		}
		sort.Slice(keys, func(a, b int) bool { return keys[a] < keys[b] })
		if len(keys) > 5 {
			keys = keys[len(keys)-5:]
		}
		fmt.Printf("--- round %d ---\n", round)
		for _, ts := range keys {
			b := merged[ts]
			fmt.Printf("%s avgClose=%.2f volume=%.4f sources=%d\n",
				time.UnixMilli(ts).UTC().Format(time.RFC3339), b.sumClose/float64(b.count), b.volume, b.count)
		}
		if round < rounds {
			time.Sleep(10 * time.Second)
		}
	}
}
```

