Build a triangular arbitrage check on bi.ts:
Fetch the `BTC/USDT`, `ETH/BTC` and `ETH/USDT` tickers on binance and compute both triangle directions from bid/ask prices, net of a 0.1% taker fee per leg, flagging any loop that returns more than you started with.

```typescript
import ccxt from 'ccxt';

const exchange = new ccxt.binance();
const fee = 0.001; // 0.1% taker fee per leg
const start = 1000; // USDT

const btcUsdt = await exchange.fetchTicker('BTC/USDT');
const ethBtc = await exchange.fetchTicker('ETH/BTC');
const ethUsdt = await exchange.fetchTicker('ETH/USDT');

const k = 1 - fee;
// USDT -> BTC -> ETH -> USDT
const forward = (((start / (btcUsdt.ask ?? Infinity)) * k / (ethBtc.ask ?? Infinity)) * k * (ethUsdt.bid ?? 0)) * k;
// USDT -> ETH -> BTC -> USDT
const reverse = (((start / (ethUsdt.ask ?? Infinity)) * k * (ethBtc.bid ?? 0)) * k * (btcUsdt.bid ?? 0)) * k;

for (const [name, result] of [['USDT->BTC->ETH->USDT', forward], ['USDT->ETH->BTC->USDT', reverse]] as const) {
    const profitPct = ((result - start) / start) * 100;
    console.log(`${name}: ${start} -> ${result.toFixed(4)} USDT (${profitPct.toFixed(4)}%)${result > start ? '  <-- ARBITRAGE' : ''}`);
}
```

