Build a triangular arbitrage check on bi.go:
Fetch the `BTC/USDT`, `ETH/BTC` and `ETH/USDT` tickers on binance and compute both triangle directions from bid/ask prices, net of a 0.1% taker fee per leg, flagging any loop that returns more than you started with.

```go
package main

import (
	"fmt"
	"math"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func price(p *float64, fallback float64) float64 {
	if p == nil || *p == 0 {
		return fallback
	}
	return *p
}

func main() {
	exchange := ccxt.NewBinance(nil)
	fee := 0.001   // 0.1% taker fee per leg
	start := 1000.0 // USDT

	btcUsdt, err := exchange.FetchTicker("BTC/USDT")
	if err != nil {
		fmt.Println(err)
		return
	}
	ethBtc, err := exchange.FetchTicker("ETH/BTC")
	if err != nil {
		fmt.Println(err)
		return
	}
	ethUsdt, err := exchange.FetchTicker("ETH/USDT")
	if err != nil {
		fmt.Println(err)
		return
	}

	k := 1 - fee
	inf := math.Inf(1)
	// USDT -> BTC -> ETH -> USDT
	forward := start / price(btcUsdt.Ask, inf) * k / price(ethBtc.Ask, inf) * k * price(ethUsdt.Bid, 0) * k
	// USDT -> ETH -> BTC -> USDT
	reverse := start / price(ethUsdt.Ask, inf) * k * price(ethBtc.Bid, 0) * k * price(btcUsdt.Bid, 0) * k

	names := []string{"USDT->BTC->ETH->USDT", "USDT->ETH->BTC->USDT"}
	for i, result := range []float64{forward, reverse} {
		profitPct := (result - start) / start * 100
		flag := ""
		if result > start {
			flag = "  <-- ARBITRAGE"
		}
		fmt.Printf("%s: %v -> %.4f USDT (%.4f%%)%s\n", names[i], start, result, profitPct, flag)
	}
}
