Fetch the `BTC/USDT`, `ETH/BTC` and `ETH/USDT` tickers on binance and compute both triangle directions from bid/ask prices, net of a 0.1% taker fee per leg, flagging any loop that returns more than you started with.

```java
import io.github.ccxt.exchanges.Binance;

public class Main {
    static double price(Double p, double fallback) {
        return p == null || p == 0 ? fallback : p;
    }

    public static void main(String[] args) {
        Binance exchange = new Binance();
        double fee = 0.001; // 0.1% taker fee per leg
        double start = 1000.0; // USDT

        var btcUsdt = exchange.fetchTicker("BTC/USDT");
        var ethBtc = exchange.fetchTicker("ETH/BTC");
        var ethUsdt = exchange.fetchTicker("ETH/USDT");

        double k = 1 - fee;
        double inf = Double.POSITIVE_INFINITY;
        // USDT -> BTC -> ETH -> USDT
        double forward = start / price(btcUsdt.ask, inf) * k / price(ethBtc.ask, inf) * k * price(ethUsdt.bid, 0) * k;
        // USDT -> ETH -> BTC -> USDT
        double reverse = start / price(ethUsdt.ask, inf) * k * price(ethBtc.bid, 0) * k * price(btcUsdt.bid, 0) * k;

        String[] names = {"USDT->BTC->ETH->USDT", "USDT->ETH->BTC->USDT"};
        double[] results = {forward, reverse};
        for (int i = 0; i < 2; i++) {
            double profitPct = (results[i] - start) / start * 100;
            System.out.printf("%s: %s -> %.4f USDT (%.4f%%)%s%n", names[i], start, results[i], profitPct,
                results[i] > start ? "  <-- ARBITRAGE" : "");
        }
    }
}
