```go
package main

import (
	"fmt"
	"sort"
	"strings"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func main() {
	byCountry := map[string][]string{}
	for _, id := range ccxt.Exchanges {
		exchange, ok := ccxt.DynamicallyCreateInstance(id, nil)
		if !ok {
			continue
		}
		countries := []string{}
		if desc, ok := exchange.Describe().(map[string]any); ok {
			if list, ok := desc["countries"].([]any); ok {
				for _, c := range list {
					if s, ok := c.(string); ok {
						countries = append(countries, s)
					}
				}
			}
		}
		if len(countries) == 0 {
			countries = []string{"unknown"}
		}
		for _, country := range countries {
			byCountry[country] = append(byCountry[country], id)
		}
	}

	keys := make([]string, 0, len(byCountry))
	for country := range byCountry {
		keys = append(keys, country)
	}
	sort.Strings(keys)
	for _, country := range keys {
		fmt.Printf("%s: %s\n", country, strings.Join(byCountry[country], ", "))
	}
}
