    for (const [price, amount] of book.bids) {
        if (price === undefined || amount === undefined) continue;
        bids.set(price, (bids.get(price) ?? 0) + amount);
    }
    for (const [price, amount] of book.asks) {
        if (price === undefined || amount === undefined) continue;
        asks.set(price, (asks.get(price) ?? 0) + amount);
    }
