for (const [price, amount] of topAsks) console.log(`  ${price}\t${amount.toFixed(6)}`);
console.log('Aggregated bids (best first):');
for (const [price, amount] of topBids) console.log(`  ${price}\t${amount.toFixed(6)}`);
if (topBids.length > 0 && topAsks.length > 0) {
    console.log(`Best bid ${topBids[0][0]} / best ask ${topAsks[0][0]} / spread ${(topAsks[0][0] - topBids[0][0]).toFixed(2)}`);
}
