Aggregate order books from three exchang.go:
Fetch the `BTC/USDT` order book from binance, okx and kraken with `fetchOrderBook`, sum the amounts at each price level across venues, and print the top of the merged book (bids high to low, asks low to high).

```go
package main

import (
	"fmt"
	"sort"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func sortedLevels(levels map[float64]float64, descending bool) []float64 {
	prices := make([]float64, 0, len(levels))
	for p := range levels {
		prices = append(prices, p)
	}
	sort.Slice(prices, func(i, j int) bool {
		if descending {
			return prices[i] > prices[j]
		}
		return prices[i] < prices[j]
	})
	if len(prices) > 10 {
		prices = prices[:10]
	}
	return prices
}

func main() {
	symbol := "BTC/USDT"
	ids := []string{"binance", "okx", "kraken"}

	bids := map[float64]float64{}
	asks := map[float64]float64{}
	for _, id := range ids {
		exchange := ccxt.CreateExchange(id, nil)
		book, err := exchange.FetchOrderBook(symbol, ccxt.WithFetchOrderBookLimit(50))
		if err != nil {
			fmt.Printf("%s: %v\n", id, err)
			continue
		}
		for _, level := range book.Bids {
			if len(level) >= 2 {
				bids[level[0]] += level[1]
			}
		}
		for _, level := range book.Asks {
			if len(level) >= 2 {
				asks[level[0]] += level[1]
			}
		}
	}

	topBids := sortedLevels(bids, true)
	topAsks := sortedLevels(asks, false)
	fmt.Println("Aggregated asks (best first):")
	for _, p := range topAsks {
		fmt.Printf("  %v\t%.6f\n", p, asks[p])
	}
	fmt.Println("Aggregated bids (best first):")
	for _, p := range topBids {
		fmt.Printf("  %v\t%.6f\n", p, bids[p])
	}
	if len(topBids) > 0 && len(topAsks) > 0 {
		fmt.Printf("Best bid %v / best ask %v / spread %.2f\n", topBids[0], topAsks[0], topAsks[0]-topBids[0])
	}
}
```

