Fetch the `BTC/USDT` order book from binance, okx and kraken with `fetchOrderBook`, sum the amounts at each price level across venues, and print the top of the merged book (bids high to low, asks low to high).

```java
import io.github.ccxt.Exchange;
import io.github.ccxt.exchanges.Binance;
import io.github.ccxt.exchanges.Kraken;
import io.github.ccxt.exchanges.Okx;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

public class Main {
    public static void main(String[] args) {
        String symbol = "BTC/USDT";
        List<Exchange> exchanges = List.of(new Binance(), new Okx(), new Kraken());

        TreeMap<Double, Double> bids = new TreeMap<>(Collections.reverseOrder());
        TreeMap<Double, Double> asks = new TreeMap<>();
        for (Exchange exchange : exchanges) {
            var book = exchange.fetchOrderBook(symbol, 50L);
            for (List<Double> level : book.bids) {
                bids.merge(level.get(0), level.get(1), Double::sum);
            }
            for (List<Double> level : book.asks) {
                asks.merge(level.get(0), level.get(1), Double::sum);
            }
        }

        List<Map.Entry<Double, Double>> topBids = new ArrayList<>(bids.entrySet()).subList(0, Math.min(10, bids.size()));
        List<Map.Entry<Double, Double>> topAsks = new ArrayList<>(asks.entrySet()).subList(0, Math.min(10, asks.size()));
        System.out.println("Aggregated asks (best first):");
        for (Map.Entry<Double, Double> e : topAsks) System.out.printf("  %s\t%.6f%n", e.getKey(), e.getValue());
        System.out.println("Aggregated bids (best first):");
        for (Map.Entry<Double, Double> e : topBids) System.out.printf("  %s\t%.6f%n", e.getKey(), e.getValue());
        if (!topBids.isEmpty() && !topAsks.isEmpty()) {
            double bestBid = topBids.get(0).getKey();
            double bestAsk = topAsks.get(0).getKey();
            System.out.printf("Best bid %s / best ask %s / spread %.2f%n", bestBid, bestAsk, bestAsk - bestBid);
        }
    }
}
