Page through OHLCV with since until you.ts:
Start `since` a week back and call `fetchOHLCV` repeatedly, moving `since` to the last candle's timestamp + 1 until the newest candle reaches the current time.

```typescript
import ccxt from 'ccxt';

const exchange = new ccxt.binance();
const timeframe = '1h';
const duration = exchange.parseTimeframe(timeframe) * 1000;
const now = exchange.milliseconds();
let since = now - 7 * 24 * 60 * 60 * 1000;
const all: number[][] = [];
while (since < now) {
    const candles = await exchange.fetchOHLCV('BTC/USDT', timeframe, since, 1000);
    if (candles.length === 0) {
        break;
    }
    all.push(...candles.map((c) => c.map((v) => v ?? 0)));
    const last = candles[candles.length - 1][0] ?? now;
    console.log('fetched', candles.length, 'candles up to', exchange.iso8601(last));
    if (last + duration >= now) {
        break;
    }
    since = last + 1;
}
console.log('total candles:', all.length);
```

