while (since < end) {
    const chunk = await exchange.fetchOHLCV(symbol, timeframe, since, limit);
    if (chunk.length === 0) {
        break;
    }
    for (const candle of chunk) {
        all.push(candle.map((v) => v ?? 0));
    }
    const lastTs = chunk[chunk.length - 1][0] ?? since;
    since = lastTs + 60 * 1000;
    console.log(`fetched ${chunk.length} candles, total ${all.length}`);
}

console.log(`done: ${all.length} candles`);
