for (let page = 1; page <= maxPages; page++) {
    const params: Record<string, string> = {};
    if (after !== undefined) {
        params['after'] = after;
    }
    const orders = await exchange.fetchClosedOrders(symbol, undefined, pageSize, params);
    console.log(`page ${page}: ${orders.length} orders`);
    for (const order of orders) {
        console.log(order.id, order.datetime, order.side, order.amount, order.status);
    }
    if (orders.length < pageSize) {
        break;
    }
    after = orders[orders.length - 1].id;
}
