		if after != "" {
			params["after"] = after
		}
		orders, err := exchange.FetchClosedOrders(
			ccxt.WithFetchClosedOrdersSymbol(symbol),
			ccxt.WithFetchClosedOrdersLimit(int64(pageSize)),
			ccxt.WithFetchClosedOrdersParams(params))
		if err != nil {
			fmt.Println(err)
			return
		}
		fmt.Printf("page %d: %d orders\n", page, len(orders))
