Fetch all trades between two dates on po.ts:
Poloniex's public trades endpoint only returns the most recent trades (no time filter), so this walks your account's trade history between two dates with `fetchMyTrades`, passing `since` and the `until` param and advancing `since` past the last trade of each page.

```typescript
import ccxt from 'ccxt';

const exchange = new ccxt.poloniex({ apiKey: 'YOUR_API_KEY', secret: 'YOUR_SECRET' });
const symbol = 'BTC/USDT';
const start = exchange.parse8601('2024-01-01T00:00:00Z') ?? 0;
const end = exchange.parse8601('2024-01-31T00:00:00Z') ?? 0;
const limit = 100;
let since = start;
const all: string[] = [];

while (since < end) {
    const trades = await exchange.fetchMyTrades(symbol, since, limit, { until: end });
    if (trades.length === 0) {
        break;
    }
    for (const trade of trades) {
        all.push(`${trade.datetime} ${trade.side} ${trade.amount} @ ${trade.price}`);
    }
    const lastTs = trades[trades.length - 1].timestamp ?? end;
    since = lastTs + 1;
    if (trades.length < limit) {
        break;
    }
}

console.log(`${all.length} trades`);
for (const line of all) {
    console.log(line);
}
```

