Fetch all trades between two dates on po.java:
Poloniex's public trades endpoint only returns the most recent trades (no time filter), so this walks your account's trade history between two dates with `fetchMyTrades`, passing `since` and the `until` param and advancing `since` past the last trade of each page.

```java
import io.github.ccxt.exchanges.Poloniex;
import io.github.ccxt.types.Trade;

import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Main {
    public static void main(String[] args) {
        Map<String, Object> config = new HashMap<>();
        config.put("apiKey", "YOUR_API_KEY");
        config.put("secret", "YOUR_SECRET");
        Poloniex exchange = new Poloniex(config);
        String symbol = "BTC/USDT";
        long start = Instant.parse("2024-01-01T00:00:00Z").toEpochMilli();
        long end = Instant.parse("2024-01-31T00:00:00Z").toEpochMilli();
        long limit = 100;
        long since = start;
        List<Trade> all = new ArrayList<>();

        while (since < end) {
            Map<String, Object> params = new HashMap<>();
            params.put("until", end);
            List<Trade> trades = exchange.fetchMyTradesAsync(symbol, since, limit, params).join();
            if (trades.isEmpty()) {
                break;
            }
            all.addAll(trades);
            Long last = trades.get(trades.size() - 1).timestamp;
            since = (last != null ? last : end) + 1;
            if (trades.size() < limit) {
                break;
            }
        }

        System.out.println(all.size() + " trades");
        for (Trade trade : all) {
            System.out.println(trade.datetime + " " + trade.side + " " + trade.amount + " @ " + trade.price);
        }
    }
}
