Validate that paginated OHLCV has no gap.go:
Fetch several days of 1h candles from gate with `fetchOHLCV` and the `paginate: true` param, then check that consecutive timestamps differ by exactly one timeframe (`parseTimeframe` × 1000 ms) and report any gaps or duplicates.

```go
package main

import (
	"fmt"
	"time"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func main() {
	exchange := ccxt.NewGate(nil)
	timeframe := "1h"
	step := ccxt.ParseTimeframe(timeframe) * 1000
	since := time.Now().UnixMilli() - 7*24*60*60*1000
	candles, err := exchange.FetchOHLCV("BTC/USDT",
		ccxt.WithFetchOHLCVTimeframe(timeframe),
		ccxt.WithFetchOHLCVSince(since),
		ccxt.WithFetchOHLCVParams(map[string]interface{}{"paginate": true}))
	if err != nil {
		fmt.Println(err)
		return
	}

	gaps := 0
	for i := 1; i < len(candles); i++ {
		prev := candles[i-1].Timestamp
		curr := candles[i].Timestamp
		if curr-prev != step {
			gaps++
			fmt.Printf("gap/overlap between %s and %s (%.2f steps)\n",
				time.UnixMilli(prev).UTC().Format(time.RFC3339),
				time.UnixMilli(curr).UTC().Format(time.RFC3339),
				float64(curr-prev)/float64(step))
		}
	}
	fmt.Printf("%d candles, %d problems\n", len(candles), gaps)
	if gaps == 0 {
		fmt.Println("OK: no gaps")
	} else {
		fmt.Println("FAILED: series has gaps")
	}
}
