    console.log(`page ${page}: ${trades.length} trades`);
    for (const trade of trades) {
        console.log(trade.id, trade.datetime, trade.side, trade.amount, trade.price);
    }
    total += trades.length;
    if (trades.length < limit) {
        break;
    }
    let newest = since;
    for (const trade of trades) {
        newest = Math.max(newest, trade.timestamp ?? 0);
    }
    since = newest + 1;
    page++;
}
console.log(`total: ${total} trades`);
