		}
		history = append(history, page...)
		last := page[len(page)-1].Timestamp
		if last == nil {
			break
		}
		since = *last + 1
	}

	for _, h := range history {
		if h.Datetime != nil && h.FundingRate != nil {
			fmt.Println(*h.Datetime, *h.FundingRate)
		}
	}
	fmt.Printf("%d funding entries\n", len(history))
}
