        Bybit exchange = new Bybit();
        String symbol = "BTC/USDT:USDT";
        long end = System.currentTimeMillis();
        long since = end - 90L * 24 * 60 * 60 * 1000;
        List<FundingRateHistory> history = new ArrayList<>();

        while (since < end) {
            List<FundingRateHistory> page = exchange.fetchFundingRateHistoryAsync(symbol, since, 200L, new HashMap<>()).join();
            if (page.isEmpty()) {
                break;
            }
            history.addAll(page);
            Long last = page.get(page.size() - 1).timestamp;
            since = (last != null ? last : end) + 1;
        }

        for (FundingRateHistory h : history) {
            System.out.println(h.datetime + " " + h.fundingRate);
        }
        System.out.println(history.size() + " funding entries");
    }
}
