Retry a failed createOrder up to three t.go:
Retry `createOrder` up to three times, but only on transient `NetworkError`s (timeouts, rate limits, outages); exchange errors such as `InsufficientFunds` are not retried. Dummy keys are used, so the call will fail with an auth error.

```go
package main

import (
	"errors"
	"fmt"
	"time"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func isNetworkError(err error) bool {
	var ccxtErr *ccxt.Error
	if !errors.As(err, &ccxtErr) {
		return false
	}
	switch ccxtErr.Type {
	case ccxt.NetworkErrorErrType, ccxt.DDoSProtectionErrType, ccxt.RateLimitExceededErrType,
		ccxt.ExchangeNotAvailableErrType, ccxt.OnMaintenanceErrType, ccxt.InvalidNonceErrType,
		ccxt.RequestTimeoutErrType:
		return true
	}
	return false
}

func main() {
	exchange := ccxt.NewBybit(map[string]interface{}{"apiKey": "YOUR_API_KEY", "secret": "YOUR_SECRET"})
	maxAttempts := 3

	for attempt := 1; attempt <= maxAttempts; attempt++ {
		order, err := exchange.CreateOrder("BTC/USDT", "limit", "buy", 0.001, ccxt.WithCreateOrderPrice(20000))
		if err == nil {
			if order.Id != nil {
				fmt.Println("order placed:", *order.Id)
			}
			return
		}
		if isNetworkError(err) && attempt < maxAttempts {
			fmt.Printf("attempt %d failed (%v), retrying...\n", attempt, err)
			time.Sleep(time.Duration(attempt) * time.Second)
			continue
		}
		fmt.Println("error:", err)
		return
	}
}
```

