```go
package main

import (
	"errors"
	"fmt"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

type tickerFetcher func() (ccxt.Ticker, error)

func main() {
	binance := ccxt.NewBinance(nil)
	kraken := ccxt.NewKraken(nil)
	ids := []string{"binance", "kraken"}
	fetchers := []tickerFetcher{
		func() (ccxt.Ticker, error) { return binance.FetchTicker("BTC/USDT") },
		func() (ccxt.Ticker, error) { return kraken.FetchTicker("BTC/USDT") },
	}
	for i, fetch := range fetchers {
		ticker, err := fetch()
		if err != nil {
			var ccxtErr *ccxt.Error
			if errors.As(err, &ccxtErr) && ccxtErr.Type == ccxt.ExchangeNotAvailableErrType {
				fmt.Println(ids[i] + " is not available, trying next venue")
				continue
			}
			fmt.Println(err)
			return
		}
		if ticker.Last != nil {
			fmt.Println(ids[i], *ticker.Last)
		}
		return
	}
}
