Rotate through several proxies for publi.ts:
Keep a list of proxy URLs and assign the next one to `httpsProxy` before each public call (round-robin); replace the placeholder URLs with your own proxies.

```typescript
import ccxt from 'ccxt';

const proxies = [
    'http://proxy1.example.com:8080',
    'http://proxy2.example.com:8080',
    'http://proxy3.example.com:8080',
];
const symbols = ['BTC/USDT', 'ETH/USDT', 'SOL/USDT', 'XRP/USDT', 'DOGE/USDT', 'ADA/USDT'];

const exchange = new ccxt.binance();
for (let i = 0; i < symbols.length; i++) {
    const proxy = proxies[i % proxies.length];
    exchange.httpsProxy = proxy;
    try {
        const ticker = await exchange.fetchTicker(symbols[i]);
        console.log(`${symbols[i]} via ${proxy}: ${ticker.last ?? 0}`);
    } catch (e) {
        console.log(`${symbols[i]} via ${proxy} failed: ${e instanceof Error ? e.message : String(e)}`);
    }
}
```

