Measure request round trip time and log.ts:
Time each call with a wall clock and print a `SLOW` warning for any request whose round trip exceeds a threshold (500 ms here).

```typescript
import ccxt from 'ccxt';

const SLOW_MS = 500;
const exchange = new ccxt.binance();
const symbols = ['BTC/USDT', 'ETH/USDT', 'SOL/USDT', 'XRP/USDT', 'DOGE/USDT'];

for (const symbol of symbols) {
    const start = Date.now();
    const ticker = await exchange.fetchTicker(symbol);
    const elapsed = Date.now() - start;
    console.log(`${symbol}: last=${ticker.last ?? 0} rtt=${elapsed}ms`);
    if (elapsed > SLOW_MS) {
        console.log(`SLOW: fetchTicker(${symbol}) took ${elapsed}ms (> ${SLOW_MS}ms)`);
    }
}
```

