Measure request round trip time and log.go:
Time each call with a wall clock and print a `SLOW` warning for any request whose round trip exceeds a threshold (500 ms here).

```go
package main

import (
	"fmt"
	"time"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func main() {
	const slow = 500 * time.Millisecond
	exchange := ccxt.NewBinance(nil)
	symbols := []string{"BTC/USDT", "ETH/USDT", "SOL/USDT", "XRP/USDT", "DOGE/USDT"}

	for _, symbol := range symbols {
		start := time.Now()
		ticker, err := exchange.FetchTicker(symbol)
		elapsed := time.Since(start)
		if err != nil {
			fmt.Printf("%s: error after %v: %v\n", symbol, elapsed, err)
			continue
		}
		last := 0.0
		if ticker.Last != nil {
			last = *ticker.Last
		}
		fmt.Printf("%s: last=%v rtt=%dms\n", symbol, last, elapsed.Milliseconds())
		if elapsed > slow {
			fmt.Printf("SLOW: FetchTicker(%s) took %dms (> %dms)\n", symbol, elapsed.Milliseconds(), slow.Milliseconds())
		}
	}
}
```

