Use amountToPrecision and priceToPrecisi.go:
Load markets, round the raw amount and price with `amountToPrecision` / `priceToPrecision` (they return strings), then pass the rounded numbers to `createOrder`. Dummy keys are used, so the order call itself will be rejected.

```go
package main

import (
	"fmt"
	"strconv"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func main() {
	exchange := ccxt.NewBinance(map[string]interface{}{"apiKey": "YOUR_API_KEY", "secret": "YOUR_SECRET"})
	if _, err := exchange.LoadMarkets(); err != nil {
		fmt.Println(err)
		return
	}

	symbol := "BTC/USDT"
	rawAmount := 0.00123456789
	rawPrice := 50123.456789

	amountPtr := exchange.AmountToPrecision(symbol, rawAmount)
	pricePtr := exchange.PriceToPrecision(symbol, rawPrice)
	if amountPtr == nil || pricePtr == nil {
		fmt.Println("could not apply precision")
		return
	}
	amountStr, priceStr := *amountPtr, *pricePtr
	fmt.Printf("amount %v -> %s, price %v -> %s\n", rawAmount, amountStr, rawPrice, priceStr)

	amount, err := strconv.ParseFloat(amountStr, 64)
	if err != nil {
		fmt.Println(err)
		return
	}
	price, err := strconv.ParseFloat(priceStr, 64)
	if err != nil {
		fmt.Println(err)
		return
	}

	order, err := exchange.CreateOrder(symbol, "limit", "buy", amount, ccxt.WithCreateOrderPrice(price))
	if err != nil {
		fmt.Println(err)
		return
	}
	if order.Id != nil {
		fmt.Println("order id:", *order.Id)
	}
}
```

