```go
package main

import (
	"encoding/json"
	"fmt"
	"os"

	ccxt "github.com/ccxt/ccxt/go/v4"
)

func main() {
	cacheFile := "markets.json"

	if _, err := os.Stat(cacheFile); err != nil {
		exchange := ccxt.NewBinance(nil)
		if _, err := exchange.LoadMarkets(); err != nil {
			fmt.Println(err)
			return
		}
		raw := map[string]any{}
		exchange.Markets.Range(func(key, value any) bool {
			raw[fmt.Sprint(key)] = value
			return true
		})
		data, err := json.Marshal(raw)
		if err != nil {
			fmt.Println(err)
			return
		}
		if err := os.WriteFile(cacheFile, data, 0644); err != nil {
			fmt.Println(err)
			return
		}
		fmt.Println("Saved", len(raw), "markets to", cacheFile)
	}

	// later: reuse the cached markets without calling the API
	data, err := os.ReadFile(cacheFile)
	if err != nil {
		fmt.Println(err)
		return
	}
	var markets map[string]any
	if err := json.Unmarshal(data, &markets); err != nil {
		fmt.Println(err)
		return
	}
	cached := ccxt.NewBinance(nil)
	cached.SetMarkets(markets)
	market := cached.GetMarket("BTC/USDT")
	if market.Id != nil {
		fmt.Println("Loaded from cache:", *market.Id)
	}
}
